`timescale 1ns/1ps

// Cross-language scoreboard: vectors are generated by case4/golden_edge.py,
// loaded with $readmemh, and compared against the packed RGB888 core by
// coordinate.  This keeps Python and RTL as independent implementations.
module tb_hex_core #(parameter DEFAULT_VECTOR_DIR="case4/tb/vectors");
    localparam integer W = 8;
    localparam integer H = 6;
    localparam integer N = W*H;
    localparam integer XB = 3;
    localparam integer YB = 3;

    logic clk = 1'b0;
    always #5 clk = ~clk;
    logic rst;
    logic in_valid, in_sof, in_eol, in_eof;
    logic [XB-1:0] in_x;
    logic [YB-1:0] in_y;
    logic [23:0] in_pixel;

    logic [23:0] input_vec [0:N-1];
    logic [7:0] gray_exp [0:N-1];
    logic [15:0] gx_exp_bits [0:N-1];
    logic [15:0] gy_exp_bits [0:N-1];
    logic [10:0] mag_exp [0:N-1];
    logic edge_exp [0:N-1];

    wire gray_valid;
    wire [XB-1:0] gray_x;
    wire [YB-1:0] gray_y;
    wire [7:0] gray_out;
    gray_rgb_stream_out #(.PIXEL_FORMAT(1), .X_BITS(XB), .Y_BITS(YB)) u_gray (
        .clk(clk), .rst(rst), .in_valid(in_valid), .in_sof(in_sof),
        .in_eol(in_eol), .in_eof(in_eof), .in_x(in_x), .in_y(in_y),
        .in_pixel(in_pixel), .out_valid(gray_valid), .out_sof(),
        .out_eol(), .out_eof(), .out_x(gray_x), .out_y(gray_y),
        .out_gray(gray_out), .out_acc()
    );

    wire core_valid, core_win_valid, core_sof, core_eol, core_eof, core_edge;
    wire [XB-1:0] core_x;
    wire [YB-1:0] core_y;
    wire signed [11:0] core_gx, core_gy;
    wire [10:0] core_mag;
    case4_gray_sobel_core #(
        .PIXEL_FORMAT(1), .IMG_WIDTH(W), .IMG_HEIGHT(H),
        .X_BITS(XB), .Y_BITS(YB), .MAG_W(11)
    ) u_core (
        .clk(clk), .rst(rst), .in_valid(in_valid), .in_sof(in_sof),
        .in_eol(in_eol), .in_eof(in_eof), .in_x(in_x), .in_y(in_y),
        .in_pixel(in_pixel), .threshold(11'd100),
        .out_valid(core_valid), .out_win_valid(core_win_valid),
        .out_sof(core_sof), .out_eol(core_eol), .out_eof(core_eof),
        .out_x(core_x), .out_y(core_y), .out_gx(core_gx), .out_gy(core_gy),
        .out_magnitude(core_mag), .out_edge(core_edge)
    );

    string vectors_dir;
    integer i, errors, gray_count, core_count, idx;
    integer exp_gx_i, exp_gy_i;
    initial begin
        if (!$value$plusargs("VECTORS_DIR=%s", vectors_dir)) vectors_dir=DEFAULT_VECTOR_DIR;
        $readmemh({vectors_dir,"/small_input_rgb888.hex"}, input_vec);
        $readmemh({vectors_dir,"/small_gray_fixed.hex"}, gray_exp);
        $readmemh({vectors_dir,"/small_gx_s16.hex"}, gx_exp_bits);
        $readmemh({vectors_dir,"/small_gy_s16.hex"}, gy_exp_bits);
        $readmemh({vectors_dir,"/small_magnitude_u11.hex"}, mag_exp);
        $readmemh({vectors_dir,"/small_edge.hex"}, edge_exp);

        errors = 0;
        gray_count = 0;
        core_count = 0;
        rst = 1'b1;
        in_valid = 1'b0;
        in_sof = 1'b0;
        in_eol = 1'b0;
        in_eof = 1'b0;
        in_x = '0;
        in_y = '0;
        in_pixel = '0;
        repeat (3) @(posedge clk);
        rst = 1'b0;

        for (i = 0; i < N; i = i + 1) begin
            @(negedge clk);
            in_valid = 1'b1;
            in_sof = (i == 0);
            in_eol = ((i % W) == W-1);
            in_eof = (i == N-1);
            in_x = i % W;
            in_y = i / W;
            in_pixel = input_vec[i];
        end
        repeat (10) begin
            @(negedge clk);
            in_valid = 1'b0;
            in_sof = 1'b0;
            in_eol = 1'b0;
            in_eof = 1'b0;
        end
        @(posedge clk);
        #2;
        if (gray_count !== N) begin
            $display("ERROR Python gray count=%0d expected=%0d", gray_count,N);
            errors = errors + 1;
        end
        if (core_count !== (W-2)*(H-2)) begin
            $display("ERROR Python core count=%0d expected=%0d", core_count,(W-2)*(H-2));
            errors = errors + 1;
        end
        if (errors == 0)
            $display("TB_HEX_CORE PASS: Python Golden vectors match RTL");
        else
            $fatal(1, "TB_HEX_CORE FAIL errors=%0d", errors);
        $finish;
    end

    always @(posedge clk) begin
        #1;
        if (!rst && gray_valid) begin
            idx = gray_y*W + gray_x;
            gray_count = gray_count + 1;
            if (gray_out !== gray_exp[idx]) begin
                $display("ERROR gray idx=%0d exp=%h got=%h",idx,gray_exp[idx],gray_out);
                errors = errors + 1;
            end
        end
        if (!rst && core_valid) begin
            idx = core_y*W + core_x;
            core_count = core_count + 1;
            exp_gx_i = $signed(gx_exp_bits[idx]);
            exp_gy_i = $signed(gy_exp_bits[idx]);
            if (!core_win_valid || $signed(core_gx) !== exp_gx_i ||
                $signed(core_gy) !== exp_gy_i || core_mag !== mag_exp[idx] ||
                core_edge !== edge_exp[idx]) begin
                $display("ERROR core idx=%0d (%0d,%0d) exp gx=%0d gy=%0d mag=%0d edge=%b got gx=%0d gy=%0d mag=%0d edge=%b",
                         idx,core_x,core_y,exp_gx_i,exp_gy_i,mag_exp[idx],edge_exp[idx],
                         core_gx,core_gy,core_mag,core_edge);
                errors = errors + 1;
            end
        end
    end
endmodule
